    {'ll': [-71.0598, 42.3584], 'label': 'Boston', 'date': 'Charles River bridges', 'acc': True, 'dy': -8, 'plate': {'kicker': 'US3.12 · the Taney Court', 'title': 'Charles River Bridge v. Warren Bridge', 'sub': '14 February 1837', 'text': "[[c-us3-court-crb]] [[c-us3-court-taney]] [[c-us3-court-taney-rep]]", 'sources': ['us3c-justia-crb', 'us3c-usreports-crb', 'us3c-schs-taney']}},
